const src = `'use strict';

/**
 * Unit cube (side = 1) centered at the origin: 8 vertices, 12 triangles.
 * Winding is counter-clockwise seen from outside, so (b-a) x (c-a) points outward.
 */

const CUBE_POSITIONS = [
  [-0.5, -0.5, -0.5], // 0
  [ 0.5, -0.5, -0.5], // 1
  [ 0.5,  0.5, -0.5], // 2
  [-0.5,  0.5, -0.5], // 3
  [-0.5, -0.5,  0.5], // 4
  [ 0.5, -0.5,  0.5], // 5
  [ 0.5,  0.5,  0.5], // 6
  [-0.5,  0.5,  0.5]  // 7
];

const CUBE_INDICES = [
  4, 5, 6,  4, 6, 7, // +Z front
  0, 3, 2,  0, 2, 1, // -Z back
  1, 2, 6,  1, 6, 5, // +X right
  0, 4, 7,  0, 7, 3, // -X left
  3, 7, 6,  3, 6, 2, // +Y top
  0, 1, 5,  0, 5, 4  // -Y bottom
];

function createCube() {
  return {
    positions: CUBE_POSITIONS.map(function (p) { return p.slice(); }),
    indices: CUBE_INDICES.slice()
  };
}

function vertexCount(positions) {
  if (typeof positions[0] === 'number') return Math.floor(positions.length / 3);
  return positions.length;
}

function getVertex(positions, i) {
  const p = positions[i];
  if (typeof p === 'number') return [positions[i * 3], positions[i * 3 + 1], positions[i * 3 + 2]];
  return [p[0], p[1], p[2]];
}

function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function normalize(a) {
  const len = Math.sqrt(dot(a, a));
  if (len === 0) return [0, 0, 0];
  return [a[0] / len, a[1] / len, a[2] / len];
}

function centroidOf(positions) {
  const n = vertexCount(positions);
  const c = [0, 0, 0];
  for (let i = 0; i < n; i++) {
    const p = getVertex(positions, i);
    c[0] += p[0]; c[1] += p[1]; c[2] += p[2];
  }
  if (n === 0) return c;
  return [c[0] / n, c[1] / n, c[2] / n];
}

function faceNormal(positions, ia, ib, ic) {
  const a = getVertex(positions, ia);
  const b = getVertex(positions, ib);
  const c = getVertex(positions, ic);
  return normalize(cross(sub(b, a), sub(c, a)));
}

function faceCenter(positions, ia, ib, ic) {
  const a = getVertex(positions, ia);
  const b = getVertex(positions, ib);
  const c = getVertex(positions, ic);
  return [(a[0] + b[0] + c[0]) / 3, (a[1] + b[1] + c[1]) / 3, (a[2] + b[2] + c[2]) / 3];
}

/** A face is "inward" when its normal points toward the mesh centroid. */
function audit(geometry) {
  const positions = geometry.positions;
  const indices = geometry.indices;
  const centroid = centroidOf(positions);

  let faces = 0;
  let inwardFaces = 0;

  for (let f = 0; f + 2 < indices.length; f += 3) {
    const ia = indices[f], ib = indices[f + 1], ic = indices[f + 2];
    const n = faceNormal(positions, ia, ib, ic);
    const c = faceCenter(positions, ia, ib, ic);
    const d = dot(n, sub(c, centroid));
    faces++;
    if (d < -1e-9) inwardFaces++;
  }

  const facesOutwardRatio = faces === 0 ? 1 : (faces - inwardFaces) / faces;
  return { faces: faces, inwardFaces: inwardFaces, facesOutwardRatio: facesOutwardRatio };
}

module.exports = {
  createCube: createCube,
  audit: audit,
  faceNormal: faceNormal,
  centroidOf: centroidOf,
  CUBE_POSITIONS: CUBE_POSITIONS,
  CUBE_INDICES: CUBE_INDICES
};

if (require.main === module) {
  const result = audit(createCube());
  console.log(JSON.stringify(result));
  console.log('DONE: cube audit printed');
}
`;

